export class Flat2DIndex {
    _getIndex;
    _getXY;
    position;
    bounds;
    constructor(_getIndex, _getXY) {
        this._getIndex = _getIndex;
        this._getXY = _getXY;
        this.position = [0, 0];
        this.bounds = [1, 1];
    }
    static GetXYOrder() {
        return new Flat2DIndex((position, bounds) => position[0] + position[1] * bounds[0], (index, bounds, position) => {
            position[1] = Math.floor(index / bounds[0]);
            position[0] = Math.floor(index % bounds[0]);
        });
    }
    get size() {
        return this.bounds[0] * this.bounds[1];
    }
    getIndex(position) {
        return this._getIndex(position, this.bounds);
    }
    getIndexVec2Array(position) {
        this.position[0] = position[0];
        this.position[1] = position[1];
        return this._getIndex(this.position, this.bounds);
    }
    getIndexXY(x, y) {
        this.position[0] = x;
        this.position[1] = y;
        return this._getIndex(this.position, this.bounds);
    }
    output = [0, 0];
    getXY(index) {
        this._getXY(index, this.bounds, this.output);
        return this.output;
    }
    getBounds() {
        return this.bounds;
    }
    setBounds(x, y) {
        this.bounds[0] = x;
        this.bounds[1] = y;
    }
}
